from __future__ import annotations

from datetime import datetime, timezone

from gitseed.application import execute
from gitseed.collect.search import Candidate, CollectResult
from gitseed.grade.types import GradeResult
from gitseed.pipeline.run import FetchedFiles
from gitseed.ports import RepositoryMetadata, RunPorts, RunRequest
from gitseed.scoring import ScoreInputs
from gitseed.storage import SQLiteRunStore


class Repository:
    def __init__(self, candidate: Candidate) -> None:
        self.candidate = candidate

    def search(self, query: str, limit: int) -> CollectResult:
        return CollectResult(candidates=[self.candidate], pages_fetched=1)

    def metadata(self, candidate: Candidate, at: datetime) -> RepositoryMetadata:
        return RepositoryMetadata(ScoreInputs(True, True, True))


class Files:
    def read(self, candidate: Candidate) -> FetchedFiles:
        return FetchedFiles((("main.py", "print('ok')\n"),))


class Model:
    def evaluate(self, digest: str) -> GradeResult:
        return GradeResult(8, 7, "fixture", "fixture", 0.0, "fixture-v1")

    def flags_malicious(self, digest: str) -> bool:
        return False


class Clock:
    def __init__(self, now: datetime) -> None:
        self.now_value = now

    def now(self) -> datetime:
        return self.now_value


def recorded_artifact(repo: str, stars: int, observed_at: datetime):
    candidate = Candidate(
        repo=repo,
        owner="org",
        html_url=f"https://github.com/{repo}",
        stars=stars,
        pushed_at="2026-01-01T00:00:00Z",
    )
    return execute(
        RunRequest("example", 1),
        RunPorts(Repository(candidate), Files(), Model(), Clock(observed_at)),
    )


def test_bounded_history_and_observation_reads_return_the_latest_slice_in_append_order(tmp_path) -> None:
    timestamps = (
        datetime(2026, 1, 1, tzinfo=timezone.utc),
        datetime(2026, 1, 2, tzinfo=timezone.utc),
        datetime(2026, 1, 3, tzinfo=timezone.utc),
    )

    with SQLiteRunStore(tmp_path / "runs.db") as store:
        for number, observed_at in enumerate(timestamps, start=1):
            store.save(
                f"run-{number}",
                recorded_artifact(f"org/repo-{number}", number * 10, observed_at),
            )

        recent_runs = store.history(limit=2)
        recent_observations = store.observations(limit=2)

    assert [stored.run_id for stored in recent_runs] == ["run-2", "run-3"]
    assert [stored.artifact.collection.candidates[0].repo for stored in recent_runs] == [
        "org/repo-2",
        "org/repo-3",
    ]
    assert [(observation.run_id, observation.repo, observation.stars) for observation in recent_observations] == [
        ("run-2", "org/repo-2", 20),
        ("run-3", "org/repo-3", 30),
    ]
    assert [observation.observed_at for observation in recent_observations] == list(timestamps[1:])
